#!/usr/bin/env bash
set -euo pipefail
sequence=43
echo "channel=kalmannet-daily-perbasin sequence=$sequence purpose=isolated-historyfix1-deployment-no-training"
date -Is
hostname
export PYTHONDONTWRITEBYTECODE=1 PYTHONOPTIMIZE=0
export OMP_NUM_THREADS=4 MKL_NUM_THREADS=4 OPENBLAS_NUM_THREADS=4 NUMEXPR_NUM_THREADS=4
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_DEPLOY'
import base64,hashlib,importlib.util,io,json,os,pathlib,re,subprocess,sys,tarfile
root=pathlib.Path('/data1/home/sunyiq/kalmannet_daily_camels_per_basin_pilots_20260901')
old_source=root/'deployments/DAILY_CAMELS_KNET_PER_BASIN_V2_BUNDLE_DEPLOY1_SEQ34/source'
dest=root/'deployments/DAILY_CAMELS_KNET_PER_BASIN_V2_BUNDLE_HISTORYFIX1_DEPLOY_SEQ43'
sha=lambda data:hashlib.sha256(data).hexdigest()
def require(condition,message):
    if not condition: raise RuntimeError(message)
def run(args):
    p=subprocess.run(args,capture_output=True,text=True,timeout=45)
    print(json.dumps({'command':args,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}),flush=True)
    require(p.returncode==0,'read-only scheduler command failed')
    return p.stdout
require(root.is_dir() and root.resolve()==root and not root.is_symlink(),'root differs')
require(dest.parent.is_dir() and dest.parent.resolve()==dest.parent and not dest.parent.is_symlink(),'deployment parent differs')
require(not dest.exists() and not dest.is_symlink(),'new deployment collision')
expected_runs=[
 'DAILY_CAMELS_KNET_PER_BASIN_PILOT_04105700_A800_TRAIN3_SEQ13',
 'DAILY_CAMELS_KNET_PER_BASIN_PILOT_08070200_A800_TRAIN1_SEQ18',
 'DAILY_CAMELS_KNET_PER_BASIN_PILOT_09035800_A800_TRAIN1_SEQ24',
 'DAILY_CAMELS_KNET_PER_BASIN_PILOT_04105700_V2_20260902_A43_A800_TRAIN1_SEQ41']
failed=root/'runs'/expected_runs[-1]
def preserved_snapshot():
    require(sorted(p.name for p in (root/'runs').iterdir())==sorted(expected_runs),'run namespace drift')
    mb=(old_source/'bundle_manifest.json').read_bytes()
    require(sha(mb)=='5abaa07cfc00e2795a91a8cd70bb793e5cf362971fd04a2de44cbf3e15fa587f','old manifest drift')
    old_manifest=json.loads(mb)
    actual={p.relative_to(old_source).as_posix():p for p in old_source.rglob('*') if p.is_file()}
    require(set(actual)==set(old_manifest['member_sha256'])|{'bundle_manifest.json'},'old deployed inventory drift')
    for name,h in old_manifest['member_sha256'].items():
        require(not actual[name].is_symlink() and sha(actual[name].read_bytes())==h,'old source drift '+name)
    metadata={}
    for name in expected_runs:
        folder=root/'runs'/name
        require(folder.is_dir() and not folder.is_symlink(),'old run absent or linked')
        metadata[name]=[{'path':p.relative_to(folder).as_posix(),'size':p.stat().st_size,'mtime_ns':p.stat().st_mtime_ns}
                        for p in sorted(folder.rglob('*')) if p.is_file()]
    require((failed/'attempts/epoch_001.started.json').is_file(),'old failure marker missing')
    require((failed/'checkpoints/epoch_000.pt').is_file(),'old initial checkpoint missing')
    require(not (failed/'checkpoints/epoch_001.pt').exists() and not (failed/'completion.marker.json').exists(),'old failure was rewritten')
    return {'old_deployment_members':len(actual),'run_names':sorted(expected_runs),
            'old_run_file_metadata':metadata,
            'failed_run_file_sha256':{p.relative_to(failed).as_posix():sha(p.read_bytes()) for p in sorted(failed.rglob('*')) if p.is_file()}}
before=preserved_snapshot()
queue=run(['squeue','-h','-u',str(os.getuid()),'-o','%i|%200j|%T|%N'])
require(not any(re.search(r'kdpp|DAILY_CAMELS_KNET_PER_BASIN|kalmannet.daily.perbasin',line,re.I) for line in queue.splitlines()),'related active job exists')
locks=root/'status/locks'
require(not locks.is_symlink() and (not locks.exists() or not list(locks.iterdir())),'existing task lock')
run(['scontrol','show','node','ngu203'])
run(['scontrol','-o','show','reservation'])
require(sys.version.split()[0]=='3.11.13','registered interpreter changed')
print(json.dumps({'pytest_available':importlib.util.find_spec('pytest') is not None,'scientific_training_submissions':0}),flush=True)
data=base64.b64decode('',validate=True)
require(len(data)==442374 and sha(data)=='737d7044e6c239d16a13d28ce1d7bd62fe8f58c6bd304ee89b3a681edc230c38','embedded archive mismatch')
with tarfile.open(fileobj=io.BytesIO(data),mode='r:gz') as tar:
    members=tar.getmembers()
    names=[m.name for m in members]
    require(len(names)==len(set(names))==51,'bundle count differs')
    for member in members:
        path=pathlib.PurePosixPath(member.name)
        require(member.isfile() and not member.issym() and not member.islnk(),'unsafe member type')
        require(not path.is_absolute() and '..' not in path.parts and str(path)==member.name and chr(92) not in member.name,'unsafe member path')
    payload={m.name:tar.extractfile(m).read() for m in members}
mb=payload['bundle_manifest.json']
require(sha(mb)=='39b0539bbdc14df2f443c3e6a548952c5ba2fe28bf650cc7be5b12f8bce0ad7f','internal manifest mismatch')
manifest=json.loads(mb)
require(len(manifest['member_sha256'])==manifest['member_count']==50,'payload member count differs')
require(set(payload)==set(manifest['member_sha256'])|{'bundle_manifest.json'},'payload set differs')
require(manifest['formal_evaluation_member_count']==manifest['historical_evaluation_member_count']==0,'forbidden evaluation member')
require(manifest['formal_evaluation_enabled'] is False and manifest['regional_training_enabled'] is False,'forbidden execution scope')
for name,h in manifest['member_sha256'].items():
    require(sha(payload[name])==h and len(payload[name])==manifest['member_size_bytes'][name],'payload hash/size differs')
require(manifest['member_sha256']['scripts/run_daily_camels_knet_per_basin_pilot.py']=='624339220e8e25f7d5b6645450138dd725fb5066f5cbc22b18151d0cc456bc70','repair source not approved')
require(manifest['member_sha256']['tests/test_run_daily_camels_knet_per_basin_pilot.py']=='5618d5f09f838165581164ec08ed1aebb398754d20ca203e2b12ef1598e72478','repair tests not approved')
os.umask(0o077)
dest.mkdir()
def create(path,content):
    with path.open('xb') as f:
        f.write(content);f.flush();os.fsync(f.fileno())
create(dest/'pre_deploy_preserved_snapshot.json',(json.dumps(before,sort_keys=True)+'\n').encode())
create(dest/'daily_camels_knet_per_basin_pilots_v2.tar.gz',data)
source=dest/'source';source.mkdir()
for name,content in sorted(payload.items()):
    path=source/pathlib.PurePosixPath(name)
    path.parent.mkdir(parents=True,exist_ok=True)
    create(path,content)
actual={p.relative_to(source).as_posix():p for p in source.rglob('*') if p.is_file()}
require(set(actual)==set(payload) and all(not p.is_symlink() and p.read_bytes()==payload[name] for name,p in actual.items()),'deployed bytes differ')
check=subprocess.run([sys.executable,'-B',str(source/'scripts/build_daily_camels_knet_per_basin_hpc_bundle.py'),'--inspect-root',str(source)],capture_output=True,text=True,timeout=60)
print(check.stdout,end='',flush=True);print(check.stderr,end='',file=sys.stderr,flush=True)
require(check.returncode==0,'deployed inspection failed')
require(preserved_snapshot()==before,'old protected state changed during deployment')
print(json.dumps({'status':'HISTORYFIX1_ISOLATED_DEPLOYMENT_PASS','request_sequence':43,'deployment_directory':str(dest),'source_root':str(source),'archive_bytes':len(data),'archive_sha256':sha(data),'internal_manifest_sha256':sha(mb),'deployed_files':51,'payload_members':50,'source_sha256':'624339220e8e25f7d5b6645450138dd725fb5066f5cbc22b18151d0cc456bc70','test_sha256':'5618d5f09f838165581164ec08ed1aebb398754d20ca203e2b12ef1598e72478','old_failed_job_id':223514,'old_failure_preserved':True,'old_run_namespace_unchanged':True,'old_deployment_unchanged':True,'source_checkpoint_loaded':False,'optimizer_steps':0,'training_submissions':0,'checkpoint_downloads':0,'formal_evaluation_access_count':0},sort_keys=True),flush=True)
PY_DEPLOY

